// ===================== ÉCOLE =====================
function ecole(p, b, c) {
  const ph = b.photos; const v = b.variant;
  const blob = (col, s, x, y) => `<div style="position:absolute;left:${x}px;top:${y}px;width:${s}px;height:${s}px;border-radius:42% 58% 63% 37%/41% 44% 56% 59%;background:${col}"></div>`;
  const heroes = [
    `<header style="position:relative;overflow:hidden;padding-bottom:100px">${blob('var(--ac)', 520, 980, -120)}${blob('var(--ac2)', 260, 840, 520)}<div style="position:relative">${nav(p, b, ['Cours', 'Tarifs', 'Inscription'], { cta: c.cta })}<div class="wrap" style="display:grid;grid-template-columns:1.1fr 1fr;gap:40px;align-items:center;padding-top:40px"><div><div class="cap">${esc(p.s)} · ${esc(p.c)}</div><h1 style="font-size:100px;margin:22px 0;font-weight:800">${esc(c.tagline)}</h1><p style="font-size:20px;opacity:.8;max-width:560px">${esc(c.intro)}</p><div style="display:flex;gap:14px;margin-top:34px"><span class="btn">${c.cta}</span><span class="btn o">Cours d'essai gratuit</span></div></div><div class="ph" style="height:600px;border-radius:50% 50% 30px 30px;border:12px solid var(--bg);background-image:url('${ph[0]}')"></div></div></div></header>`,
    `<header style="background:var(--ac);color:#111">${nav(p, b, ['Programmes', 'Vie étudiante', 'Admissions'], { color: '#111' })}<div class="wrap" style="padding-top:20px;padding-bottom:0"><h1 style="font-size:160px;font-weight:800;line-height:.9;letter-spacing:-4px">${esc(c.tagline)}</h1></div><div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:16px;padding:50px 96px 0">${[0, 1, 2].map((i) => `<div class="ph" style="height:380px;border-radius:30px 30px 0 0;background-image:url('${ph[i]}')"></div>`).join('')}</div></header>`,
    `<header style="position:relative;height:880px;color:#fff;overflow:hidden"><div class="ph" style="position:absolute;inset:0;background-image:linear-gradient(120deg,${b.pal.bg}f2 35%,${b.pal.bg}66),url('${ph[0]}')"></div>${nav(p, b, ['Formations', 'Calendrier', 'Contact'], { abs: 1, color: b.pal.ink, cta: c.cta })}<div style="position:absolute;left:96px;top:240px;max-width:760px;color:var(--ink)"><h1 style="font-size:104px;font-weight:800">${esc(c.tagline)}</h1><p style="font-size:20px;margin:24px 0 34px;opacity:.85">${esc(c.intro)}</p><div style="display:flex;gap:14px"><span class="btn">${c.cta}</span><span class="btn o">Brochure PDF</span></div></div>${c.music ? `<svg style="position:absolute;right:60px;bottom:80px" width="560" height="160">${Array.from({ length: 40 }, (_, i) => `<rect x="${i * 14}" y="${80 - (20 + Math.abs(Math.sin(i * 0.7) * 60)) / 2}" width="8" height="${20 + Math.abs(Math.sin(i * 0.7) * 60)}" rx="4" fill="${b.pal.accent}"/>`).join('')}</svg>` : ''}</header>`,
  ];
  return shell(p, b, '', `${heroes[v]}
  <section class="wrap" style="padding-top:110px;padding-bottom:110px"><div class="cap">${c.music ? 'Nos cours' : 'Nos formations'}</div><h2 style="font-size:66px;margin:12px 0 44px;font-weight:800">Trouvez votre voie</h2><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:22px">${c.items.map(([t, d], i) => `<div style="background:${i % 2 ? 'var(--soft)' : 'var(--ac2)'};color:${i % 2 ? 'var(--ink)' : '#fff'};border-radius:28px;padding:34px;min-height:230px;display:flex;flex-direction:column;justify-content:space-between"><span style="opacity:.8">${ico(c.music ? 'ecole' : 'ecole2', 34)}</span><div><h3 style="font-size:34px;font-weight:800">${t}</h3><div style="opacity:.8;margin-top:4px">${d}</div></div></div>`).join('')}</div></section>
  <section style="padding:100px 96px;background:var(--soft);display:grid;grid-template-columns:1fr 1fr;gap:70px;align-items:center"><div class="ph" style="height:460px;border-radius:30px;background-image:url('${ph[1]}')"></div><div><div class="cap">Inscriptions ouvertes</div><h2 style="font-size:60px;margin:14px 0;font-weight:800">Rentrée de janvier 2027</h2><p style="font-size:19px;opacity:.8">Places limitées par groupe. Réservez votre séance d'essai ou votre entretien d'admission en ligne.</p><div style="display:flex;gap:14px;margin-top:30px"><span class="btn">${c.cta}</span><span class="btn o">${ico('phone', 18)} ${esc(c.phone)}</span></div></div></section>
  ${footer(p, b, c, true)}`);
}

// ===================== LUXE =====================
function luxe(p, b, c) {
  const ph = b.photos; const v = b.variant;
  const heroes = [
    `<header style="height:900px;display:grid;grid-template-columns:1fr 1fr">${''}<div style="display:flex;flex-direction:column">${nav(p, b, ['Collection', 'Maison', 'Boutique'], {})}<div style="flex:1;display:flex;flex-direction:column;justify-content:center;padding:0 96px;gap:30px"><div class="cap" style="letter-spacing:8px">${esc(p.s)} — ${esc(p.c)}</div><h1 style="font-size:110px;font-weight:400;line-height:.98">${esc(c.tagline)}</h1><div style="width:80px;height:1px;background:var(--ac)"></div><p style="font-size:18px;opacity:.75;max-width:460px">${esc(c.intro)}</p><span style="text-transform:uppercase;letter-spacing:4px;font-size:13px;border-bottom:1px solid var(--ac);width:max-content;padding-bottom:6px">${c.cta}</span></div></div><div class="ph" style="background-image:url('${ph[0]}')"></div></header>`,
    `<header style="position:relative;height:920px;color:#fff;text-align:center"><div class="ph" style="position:absolute;inset:0;background-image:linear-gradient(180deg,rgba(0,0,0,.4),rgba(0,0,0,.55)),url('${ph[0]}')"></div><div style="position:relative;display:flex;justify-content:center;padding-top:40px">${headerLogo(p, b, { h: 70, onDark: 1, ink: '#fff' })}</div><div style="position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:26px"><div class="cap" style="letter-spacing:10px;color:#fff">Nouvelle collection</div><h1 style="font-size:132px;font-weight:400;max-width:1200px">${esc(c.tagline)}</h1><span style="text-transform:uppercase;letter-spacing:4px;font-size:13px;border:1px solid #fff;padding:16px 30px">${c.cta}</span></div></header>`,
    `<header>${nav(p, b, ['Collection', 'Histoire', 'Contact'], {})}<div style="text-align:center;padding:30px 0 60px"><h1 style="font-size:210px;font-weight:400;letter-spacing:-6px;line-height:.85;text-transform:uppercase">${esc(b.main)}</h1><div class="cap" style="letter-spacing:10px;margin-top:20px">${esc(c.tagline)}</div></div><div style="display:grid;grid-template-columns:1fr 1.4fr 1fr;gap:20px;padding:0 96px;align-items:center"><div class="ph" style="height:440px;background-image:url('${ph[1]}')"></div><div class="ph" style="height:620px;background-image:url('${ph[0]}')"></div><div class="ph" style="height:440px;background-image:url('${ph[2]}')"></div></div></header>`,
  ];
  return shell(p, b, '', `${heroes[v]}
  <section class="wrap" style="padding-top:130px;padding-bottom:130px"><div style="text-align:center"><div class="cap" style="letter-spacing:8px">La sélection</div><h2 style="font-size:72px;font-weight:400;margin-top:16px">Pièces signatures</h2></div><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:36px;margin-top:60px">${c.items.map(([t, d, pr], i) => `<div style="text-align:center"><div style="background:var(--soft);height:460px;display:flex;align-items:center;justify-content:center;overflow:hidden"><div class="ph" style="width:78%;height:78%;background-image:url('${ph[(i + 1) % ph.length]}')"></div></div><h3 style="font-size:30px;font-weight:400;margin-top:22px">${t}</h3><div style="opacity:.6;font-size:14px;letter-spacing:2px;text-transform:uppercase;margin:6px 0">${d}</div><div style="color:var(--ac)">${price(pr)}</div></div>`).join('')}</div></section>
  <section style="display:grid;grid-template-columns:1fr 1fr;background:var(--soft)"><div class="ph" style="height:620px;background-image:url('${ph[2] || ph[0]}')"></div><div style="padding:110px 96px;display:flex;flex-direction:column;justify-content:center;gap:24px"><div class="cap" style="letter-spacing:8px">La maison</div><h2 style="font-size:60px;font-weight:400">Le goût du détail, depuis ${esc(p.c)}</h2><p style="opacity:.75;font-size:18px">${esc(c.intro)} Livraison soignée et conseils personnalisés sur rendez-vous.</p><span style="text-transform:uppercase;letter-spacing:4px;font-size:13px;border-bottom:1px solid var(--ac);width:max-content;padding-bottom:6px">Prendre rendez-vous</span></div></section>
  ${footer(p, b, c, /^#0|^#1/.test(b.pal.bg) ? false : true)}`);
}

// ===================== BOUTIQUE =====================
function boutique(p, b, c) {
  const ph = b.photos; const v = b.variant;
  const heroes = [
    `<header style="position:relative;overflow:hidden;padding-bottom:80px">${nav(p, b, ['Boutique', 'Nouveautés', 'Livraison'], { cta: c.cta })}<div class="wrap" style="display:grid;grid-template-columns:1fr 1fr;gap:40px;align-items:center;padding-top:30px"><div><span style="display:inline-block;background:var(--ac2);color:#fff;padding:8px 16px;border-radius:999px;font-weight:700;transform:rotate(-3deg)">Livraison à ${esc(p.c)} 🚚</span><h1 style="font-size:110px;margin:26px 0;font-weight:700">${esc(c.tagline)}</h1><p style="font-size:20px;opacity:.8;max-width:520px">${esc(c.intro)}</p><span class="btn" style="margin-top:30px">${ico('chat', 18)} ${c.cta}</span></div><div style="position:relative;height:620px"><div style="position:absolute;inset:30px;border-radius:50%;background:var(--ac)"></div><div class="ph" style="position:absolute;inset:70px;border-radius:50%;background-image:url('${ph[0]}')"></div><div class="ph" style="position:absolute;right:0;bottom:20px;width:200px;height:200px;border-radius:30px;border:8px solid var(--bg);transform:rotate(8deg);background-image:url('${ph[1]}')"></div></div></div></header>`,
    `<header style="background:var(--ac);color:#fff">${nav(p, b, ['Shop', 'Idées cadeaux', 'Contact'], { color: '#fff', onDark: 1, ink: '#fff' })}<div style="display:grid;grid-template-columns:1.1fr 1fr;gap:40px;padding:20px 96px 80px;align-items:center"><h1 style="font-size:130px;font-weight:700;line-height:.92">${esc(c.tagline)}</h1><div style="display:grid;grid-template-columns:1fr 1fr;gap:14px">${[0, 1, 2, 3].map((i) => `<div class="ph" style="height:240px;border-radius:${['120px 120px 20px 20px', '20px', '20px', '20px 20px 120px 120px'][i]};background-image:url('${ph[i % ph.length]}')"></div>`).join('')}</div></div></header>`,
    `<header>${nav(p, b, ['Catalogue', 'Sur mesure', 'Contact'], { cta: c.cta })}<div style="margin:10px 40px 0;border-radius:40px;overflow:hidden;position:relative;height:720px;color:#fff"><div class="ph" style="position:absolute;inset:0;background-image:linear-gradient(90deg,rgba(0,0,0,.6),transparent 70%),url('${ph[0]}')"></div><div style="position:absolute;left:70px;bottom:80px;max-width:700px"><h1 style="font-size:110px;font-weight:700">${esc(c.tagline)}</h1><p style="font-size:20px;margin:18px 0 28px">${esc(c.intro)}</p><span class="btn">${c.cta}</span></div></div></header>`,
  ];
  return shell(p, b, '', `${heroes[v]}
  <section class="wrap" style="padding-top:110px;padding-bottom:110px"><div style="display:flex;justify-content:space-between;align-items:end"><h2 style="font-size:72px;font-weight:700">Nos coups de cœur</h2><span class="btn o">Tout le catalogue</span></div><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:22px;margin-top:44px">${c.items.map(([t, d, pr], i) => `<div><div class="ph" style="height:330px;border-radius:26px;background-image:url('${ph[(i + 1) % ph.length]}');position:relative"><span style="position:absolute;right:14px;top:14px;background:#fff;color:#111;width:44px;height:44px;border-radius:50%;display:flex;align-items:center;justify-content:center">${ico('heart', 20)}</span></div><h3 style="font-size:24px;margin-top:16px;font-family:var(--b);font-weight:800">${t}</h3><div style="opacity:.65">${d}</div><div style="display:flex;justify-content:space-between;align-items:center;margin-top:10px"><b style="font-size:20px;color:var(--ac)">${price(pr)}</b><span style="background:var(--ink);color:var(--bg);width:40px;height:40px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:22px">+</span></div></div>`).join('')}</div></section>
  <section style="margin:0 40px 80px;border-radius:40px;padding:80px;background:var(--ac2);color:#fff;display:flex;justify-content:space-between;align-items:center"><div><h2 style="font-size:60px;font-weight:700">Commandez en 1 message</h2><p style="font-size:19px;opacity:.9;margin-top:10px">Envoyez une photo de l'article sur WhatsApp, on s'occupe du reste. Livraison sous 24 h.</p></div><span class="btn" style="background:#fff;color:#111">${ico('chat', 18)} ${esc(c.phone)}</span></section>
  ${footer(p, b, c, false)}`);
}

// ===================== SERVICES =====================
function services(p, b, c) {
  const ph = b.photos; const dark = /^#0/.test(b.pal.bg);
  return shell(p, b, '', `<header style="position:relative;overflow:hidden;${dark ? 'background:radial-gradient(circle at 80% 20%,' + b.pal.accent + '55,transparent 50%),var(--bg)' : 'background:linear-gradient(180deg,var(--soft),var(--bg))'}">${nav(p, b, ['Services', 'Entreprises', 'Contact'], { cta: c.cta, onDark: dark, ink: dark ? b.pal.ink : undefined })}<div class="wrap" style="display:grid;grid-template-columns:1.1fr 1fr;gap:60px;align-items:center;padding-top:40px;padding-bottom:110px"><div><div class="cap">${esc(p.s)} · ${esc(p.c)}</div><h1 style="font-size:96px;margin:22px 0;font-weight:700;letter-spacing:-2px">${esc(c.tagline)}</h1><p style="font-size:20px;opacity:.8">${esc(c.intro)}</p><div style="display:flex;gap:14px;margin-top:34px"><span class="btn" style="color:#fff">${c.cta}</span><span class="btn o">${ico('phone', 18)} ${esc(c.phone)}</span></div></div><div style="position:relative;height:600px"><div class="ph" style="position:absolute;inset:0;border-radius:32px;background-image:url('${ph[0]}')"></div><div style="position:absolute;left:-40px;bottom:40px;background:#fff;color:#111;border-radius:18px;padding:20px 24px;box-shadow:0 20px 50px rgba(0,0,0,.2);display:flex;gap:14px;align-items:center"><span style="background:${b.pal.accent};color:#fff;width:46px;height:46px;border-radius:12px;display:flex;align-items:center;justify-content:center">${ico('check', 24)}</span><div><b>Réponse en moins de 2 h</b><div style="font-size:14px;opacity:.6">7 j/7 · ${esc(p.c)}</div></div></div></div></div></header>
  <section class="wrap" style="padding-top:100px;padding-bottom:100px"><h2 style="font-size:60px;font-weight:700;margin-bottom:44px">Nos services</h2><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:20px">${c.items.map(([i, t]) => `<div style="border:1.5px solid ${dark ? 'var(--soft)' : '#e5e7eb'};border-radius:24px;padding:30px;background:${dark ? 'var(--soft)' : '#fff'}"><span style="color:var(--ac)">${ico(i, 34)}</span><h3 style="font-size:24px;margin:18px 0 8px;font-family:var(--b);font-weight:700">${t}</h3><p style="opacity:.7">Une équipe disponible, des tarifs clairs et un suivi personnalisé.</p></div>`).join('')}</div></section>
  <section style="padding:90px 96px;background:linear-gradient(90deg,var(--ac),var(--ac2));color:#fff;display:flex;justify-content:space-between;align-items:center"><h2 style="font-size:58px;font-weight:700;max-width:760px">Parlons de votre besoin dès aujourd'hui</h2><span class="btn" style="background:#fff;color:#111">${c.cta}</span></section>
  ${footer(p, b, c, true)}`);
}

module.exports = { hotel, resto, beaute, immo, sante, voyage, auto, ecole, luxe, boutique, services };
